function cloneAnchor(a:GeometryAnchor):GeometryAnchor{if(a.kind==='world')return {kind:'world',point:[...a.point] as Vec3};if(a.kind==='vertex')return {kind:'vertex',objectId:a.objectId,vertexId:a.vertexId,fallback:[...a.fallback] as Vec3};return {kind:'edge',objectId:a.objectId,vertexA:a.vertexA,vertexB:a.vertexB,t:a.t,fallback:[...a.fallback] as Vec3};}
