function addGroundPrism(profile:Vec2[],height=20,holes:Vec2[][]=[],name='Extruded shape'){assertProjectObjectCapacity(1);const p=profile.map(v=>[v[0],v[1]] as Vec2),hs=holes.map(loop=>loop.map(v=>[v[0],v[1]] as Vec2));return executeDocumentCommand<ModelObject>({type:'add-ground-prism',label:'Create extruded shape',parameters:{profile:p,holes:hs,height,name},execute(){const o=makeObject('polygon',p);o.name=name;o.solid=geometryApi.createPrismRegion(p,hs,height,'s_'+o.id);objects.push(o);return {value:o,selection:{kind:'object',objectId:o.id},surfaceSketch:null};}});}
