function duplicateObject(){const sg=selectedGroup();if(sg)return duplicateGroup(sg.id);if(selectedObjectIds().length!==1){toast('Select one object to duplicate.');return;}const source=current();if(!source)return;assertProjectObjectCapacity(1,'Duplicating the object');return executeDocumentCommand<ModelObject>({type:'duplicate-object',label:'Duplicate object',parameters:{objectId:source.id,offset:[5,5,0]},execute(){const o=requireObject(source.id),n=cloneObject(o);n.id='o'+nextObjectId++;n.locked=false;n.name=o.name+' copy';n.transform.position=V.add(n.transform.position,[5,5,0]);n.solid.id='s_'+n.id;objects.push(n);return {value:n,selection:{kind:'object',objectId:n.id}};}});}

function removeObjectById(objectId:ObjectId){const grouped=groupForObjectId(objectId);if(grouped)return removeGroupById(grouped.id);const source=objects.find(o=>o.id===objectId);if(!source)return;return executeDocumentCommand<void>({type:'delete-object',label:'Delete object',parameters:{objectId:source.id},execute(){const i=objects.findIndex(x=>x.id===source.id);if(i>=0)objects.splice(i,1);for(let j=dimensions.length-1;j>=0;j--)if(dimensionReferencesObject(dimensions[j],source.id))dimensions.splice(j,1);return {selection:objects[0]?{kind:'object',objectId:objects[0].id}:dimensions[0]?{kind:'dimension',dimensionId:dimensions[0].id}:null,surfaceSketch:null};}});}
// Delete exactly the committed object selection; frame-selected group members
// must not expand to their unselected siblings. One command owns all cleanup.
function removeSelectedObjects():number {
  const ids=selectedObjectIds();if(modelingOperationBusy||!ids.length)return 0;
  const idSet=new Set(ids);
  return executeDocumentCommand<number>({type:'delete-objects',label:'Delete selected objects',parameters:{objectIds:[...ids]},execute(){
    for(let i=objects.length-1;i>=0;i--)if(idSet.has(objects[i].id))objects.splice(i,1);
    for(let i=dimensions.length-1;i>=0;i--)if(ids.some(id=>dimensionReferencesObject(dimensions[i],id)))dimensions.splice(i,1);
    for(let i=groups.length-1;i>=0;i--){
      const g=groups[i];if(!g.objectIds.some(id=>idSet.has(id)))continue;
      g.objectIds=g.objectIds.filter(id=>!idSet.has(id));
      if(g.objectIds.length<2)groups.splice(i,1);
    }
    return {value:ids.length,selection:null,objectSelection:[],surfaceSketch:null};
  }});
}
function removeObject(){const source=current();if(!source)return;return removeObjectById(source.id);}
