function addGuideCircle(center0:Vec3,normal0:Vec3,radius0:number,label='Guide circle'){const normal=V.unit(normal0),radius=clean(radius0,1e9);if(V.len(normal)<1e-9)throw Error('The guide circle requires a valid support plane.');if(!Number.isFinite(radius)||radius<TOL.minimumEdge)throw Error('The guide circle radius must be greater than 0 mm.');const center=[...center0] as Vec3;return executeDocumentCommand<GuideCircle>({type:'add-guide-circle',label:'Create guide circle',parameters:{center,normal,radius,label},execute(){const g:GuideCircle={id:'g'+nextGuideId++,kind:'circle',center,normal,radius,label};guides.push(g);return {value:g,selection:{kind:'guide',guideId:g.id}};}});}
function addGuidePlane(origin:Vec3,normal:Vec3,label='Guide plane',axis0?:Vec3){const n=V.unit(normal);if(V.len(n)<1e-9)throw Error('The guide plane requires a valid normal.');const o=[...origin] as Vec3,axis=normalizedGuidePlaneAxis(axis0,n),replacedPlaneIds=guides.filter(g=>g.kind==='plane').map(g=>g.id);return executeDocumentCommand<GuidePlane>({type:'add-guide-plane',label:replacedPlaneIds.length?'Replace split plane':'Create guide plane',parameters:{origin:o,normal:n,axis:axis||null,label,replacedPlaneIds},execute(){for(let i=guides.length-1;i>=0;i--)if(guides[i].kind==='plane')guides.splice(i,1);const g:GuidePlane={id:'g'+nextGuideId++,kind:'plane',origin:o,normal:n,axis,label};guides.push(g);return {value:g,selection:{kind:'guide',guideId:g.id}};}});}
function updateGuidePlane(id:GuideId,origin0:Vec3,normal0:Vec3,label0?:string,axis0?:Vec3|null){cancelSplitSurfaceBend();const currentPlane=guides.find(v=>v.id===id);if(!currentPlane||currentPlane.kind!=='plane')throw Error('The guide plane does not exist.');const origin=[...origin0] as Vec3,normal=V.unit(normal0),label=String(label0||'Split plane').slice(0,80);if(V.len(normal)<1e-9)throw Error('The guide plane requires a valid normal.');const axisSource=axis0===undefined?currentPlane.axis:axis0===null?undefined:axis0,guideAxis=normalizedGuidePlaneAxis(axisSource,normal)||(currentPlane.surface?planeBasis({normal,offset:V.dot(normal,origin)},origin).u:undefined);return executeDocumentCommand<GuidePlane>({type:'update-guide-plane',label:'Edit guide plane',parameters:{guideId:id,origin,normal,axis:guideAxis||null,label},execute(){const g=guides.find(v=>v.id===id);if(!g||g.kind!=='plane')throw Error('The guide plane does not exist.');g.origin=origin;g.normal=normal;g.axis=guideAxis;g.label=label;return {value:g,selection:{kind:'guide',guideId:g.id}};}});}
