function splitObjectByGuidePlane(o:ModelObject,guideId:GuideId){if(groupForObjectId(o.id))throw Error('Ungroup the object before splitting it.');const guide=guides.find(v=>v.id===guideId);if(!guide||guide.kind!=='plane')throw Error('Choose a valid split plane first.');if(guide.surface)return splitObjectByGuideSurface(o,guide);assertProjectObjectCapacity(1,'Splitting');const planeOrigin=[...guide.origin] as Vec3,planeNormal=V.unit(guide.normal);return executeDocumentCommand<ModelObject[]>({type:'split-object-plane',label:'Split object by plane',parameters:{objectId:o.id,guideId,origin:planeOrigin,normal:planeNormal,consumeGuide:true},execute(){const target=requireObject(o.id);freezeDimensionAnchorsForObjects(new Set([target.id]));const localOrigin=inverseTransformPoint(planeOrigin,target.transform),localNormal=V.unit(inverseRotate(planeNormal,target.transform.rotation)),split=geometryApi.splitByPlane(target.solid,localOrigin,localNormal);target.solid=split.positive;target.solid.id=target.solid.id||('s_'+target.id);target.solid.metadata={...target.solid.metadata,name:target.name};const id='o'+nextObjectId++,name=`${target.name} (split)`,second:ModelObject={id,name,kind:'solid',color:target.color,...(objectShininess(target)>0?{shininess:objectShininess(target)}:{}),transform:{position:[...target.transform.position] as Vec3,rotation:[...target.transform.rotation] as Vec3},solid:split.negative};second.solid.id='s_'+id;second.solid.metadata={...second.solid.metadata,name};const index=objects.findIndex(v=>v.id===target.id);objects.splice(index+1,0,second);const guideIndex=guides.findIndex(v=>v.id===guideId);if(guideIndex<0)throw Error('The split plane no longer exists.');guides.splice(guideIndex,1);return {value:[target,second],selection:{kind:'object',objectId:target.id},objectSelection:[target.id,second.id],surfaceSketch:null};}});}
